class Widget {
public:
  // A perfectly matching constructor
  Widget(int i, double d) { /* ... */ }

  // An initializer_list constructor that would require narrowing
  Widget(std::initializer_list<bool> il) { /* ... */ }
};

// OK: uses parens, calls the first constructor
Widget w1(10, 5.0); 

// ERROR: uses braces
// Widget w2{10, 5.0};
// 1. Compiler prioritizes the std::initializer_list constructor.
// 2. To call it, int(10) and double(5.0) must convert to bool.
// 3. Both are narrowing conversions, which are forbidden in braced initializers.
// 4. Code is rejected, even though a perfect non-list overload exists.
